def weather_icon_lookup(condition: str | None) -> bytes:
    """Unbekannte/leere condition -> WEATHER_ICON_DEFAULT statt KeyError,
    damit ein Tippfehler oder eine kuenftige neue HA-Condition nicht den
    ganzen Batch-Payload zum Absturz bringt."""
    return WEATHER_ICON_BITMAPS.get(condition or "", WEATHER_ICON_BITMAPS[WEATHER_ICON_DEFAULT])


def resample_1bpp(native: bytes, width: int, height: int) -> bytes:
    """Nearest-Neighbor-Resampling von der nativen WEATHER_ICON_NATIVE_SIZE x
    WEATHER_ICON_NATIVE_SIZE Bitmap auf eine beliebige Zielgroesse -- reine
    Ganzzahl-Arithmetik, identisch zum Resampling in WeatherIcons.Resample
    (C#), damit beide Renderer dieselben Icons byteidentisch skalieren."""
    width = max(1, width)
    height = max(1, height)
    if width == WEATHER_ICON_NATIVE_SIZE and height == WEATHER_ICON_NATIVE_SIZE:
        return native

    src_bytes_per_row = (WEATHER_ICON_NATIVE_SIZE + 7) // 8
    dst_bytes_per_row = (width + 7) // 8
    out = bytearray(dst_bytes_per_row * height)

    for y in range(height):
        sy = min(WEATHER_ICON_NATIVE_SIZE - 1, (y * WEATHER_ICON_NATIVE_SIZE) // height)
        for x in range(width):
            sx = min(WEATHER_ICON_NATIVE_SIZE - 1, (x * WEATHER_ICON_NATIVE_SIZE) // width)
            src_byte_index = sy * src_bytes_per_row + sx // 8
            src_bit_pos = 7 - (sx % 8)
            if native[src_byte_index] & (1 << src_bit_pos):
                dst_byte_index = y * dst_bytes_per_row + x // 8
                dst_bit_pos = 7 - (x % 8)
                out[dst_byte_index] |= 1 << dst_bit_pos

    return bytes(out)
